CREATE OR REPLACE FUNCTION public.skin_said(p_world uuid, p_stats jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  select case when coalesce((p_stats->>'aegis')::double precision, 0) <= 0 then '{}'::jsonb
              else jsonb_strip_nulls(jsonb_build_object(
                'size', (p_stats->>'aegis')::double precision,
                'by', p_stats->>'aegisBy',
                'name', (select pl.name from player pl
                          where pl.world_id = p_world and pl.uid::text = p_stats->>'aegisBy'))) end
